using Challenge;void C(string id,Func<bool> f){try{Console.WriteLine($"{id}|{(f()?"pass":"fail")}");}catch{Console.WriteLine($"{id}|fail");}}Dictionary<string,Order>D()=>new(){{"1",new("1","a","New","")}};C("C01",()=>new Orders(D()).Get("b","1") is null);C("C02",()=>{var d=D();var s=new Orders(d);return s.Update("b","1","x")=="NotFound"&&s.Cancel("b","1")=="NotFound"&&d["1"].Status=="New";});C("C03",()=>{var d=D();var s=new Orders(d);return s.Update("a","1","x")=="Ok"&&s.Cancel("a","1")=="Ok";});C("C04",()=>new Orders(D()).Update("b","1","x")==new Orders(D()).Update("b","missing","x"));C("C05",()=>{var d=D();var s=new Orders(d);return s.Get("b","1") is null&&s.Update("b","1","x")=="NotFound"&&s.Cancel("b","1")=="NotFound";});
